const $=id=>document.getElementById(id);let sound=null,element=null,source=null,gain=null,url=null,playingOfficial=false,storedFile=null;
const dbReady=new Promise(resolve=>{try{const req=indexedDB.open('twelfth-night-music',1);req.onupgradeneeded=()=>req.result.createObjectStore('audio');req.onerror=()=>resolve(null);req.onsuccess=()=>{const db=req.result,r=db.transaction('audio').objectStore('audio').get('song');r.onsuccess=()=>{storedFile=r.result??null;resolve(db);};r.onerror=()=>resolve(db);};}catch{resolve(null);}});
function external(on){if(sound){sound.externalMusic=on;sound.setMusicVolume(sound.musicVolume);}}
function command(func,args=[]){$('youtube-song').querySelector('iframe')?.contentWindow.postMessage(JSON.stringify({event:'command',func,args}),'https://www.youtube-nocookie.com');}
function volume(){if(gain)gain.gain.value=sound?.musicVolume??.5;command('setVolume',[Math.round((sound?.musicVolume??.5)*100)]);command(sound?.muted?'mute':'unMute');}
function official(){element?.pause();playingOfficial=true;external(true);$('official-player').hidden=false;const f=document.createElement('iframe');f.title='Das Beste · Silbermond 官方播放器';f.src='https://www.youtube-nocookie.com/embed/0fB_Lxu6UhQ?autoplay=1&playsinline=1&enablejsapi=1&origin='+encodeURIComponent(location.origin);f.allow='autoplay; encrypted-media; fullscreen; picture-in-picture';f.allowFullscreen=true;$('youtube-song').replaceChildren(f);f.onload=volume;$('music-panel').hidden=true;}
async function localPlay(file=storedFile){if(!file)return false;closeOfficial();if(!sound){$('music-feedback').textContent='先进入城市，再播放已导入的音乐。';return false;}sound.start();if(!element||file!==element._file){element?.pause();if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(file);element=new Audio(url);element._file=file;element.loop=true;source=sound.ctx.createMediaElementSource(element);gain=sound.ctx.createGain();source.connect(gain).connect(sound.master);}external(true);volume();await sound.ctx.resume();await element.play();return true;}
function closeOfficial(){playingOfficial=false;$('youtube-song').replaceChildren();$('official-player').hidden=true;external(!!element&&!element.paused);}
for(const id of ['music-open','intro-music'])$(id)?.addEventListener('click',()=>{$('music-panel').hidden=false;});
$('music-close').onclick=()=>{$('music-panel').hidden=true;};$('official-play').onclick=official;$('official-close').onclick=closeOfficial;
$('song-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{storedFile=file;const db=await dbReady;if(db)db.transaction('audio','readwrite').objectStore('audio').put(file,'song');$('music-feedback').textContent='已导入：'+file.name;await localPlay(file);}catch{$('music-feedback').textContent='文件已选中，进入城市后点“播放已导入音乐”。';}};
$('local-play').onclick=async()=>{if(element&&!element.paused){element.pause();external(false);return;}await dbReady;if(!storedFile){$('music-feedback').textContent='请先选择一个音频文件。';return;}try{await localPlay();}catch{$('music-feedback').textContent='这份音频未能播放，请换用 MP3 或 M4A。';}};
addEventListener('city:volume',volume);window.citySong={attach(s){sound=s;if(playingOfficial)external(true);volume();},async start(){await dbReady;if(storedFile){try{await localPlay();return;}catch{}}if(!playingOfficial)official();},pause(){element?.pause();command('pauseVideo');},resume(){if(element&&sound?.externalMusic)element.play().catch(()=>{});if(playingOfficial)command('playVideo');},restart(){if(element)element.currentTime=0;command('seekTo',[0,true]);},get official(){return playingOfficial;}};
